        for c in comps:
            mesh = c.get_editor_property('static_mesh')
            if mesh:
                print(f"  Mesh: {mesh.get_path_name()}")
            mats = c.get_materials()
            for i, m in enumerate(mats):
                if m:
                    print(f"  Material[{i}]: {m.get_path_name()}")
            vis = c.get_editor_property('visible')
            print(f"  Visible: {vis}")
        break

